BASE=Path(__file__).resolve().parents[1]
OUT=BASE/'.cache/batch200/drafts/rewrite_spec';OUT.mkdir(parents=True,exist_ok=True)
S=[['拉丁 fārī','说、讲']]
FAM=[['拉丁 fāma','人们说的话、传闻；声誉，与 fārī“说”同族'],['古法语 fame → 中古英语 fame → 英语 fame','名声、知名度']]
FAMOUS=FAM[:1]+[['拉丁 fāmōsus → 法语 famous → 中古英语 famous','被人传说、众所周知的'],['英语 famous','有名的']]
FATE=S+[['拉丁 fātum／fāta','说出的话、预言、已定的命运'],['中古英语 fate → 英语 fate','命运；最终结局']]
FATAL=FATE[:2]+[['拉丁 fātālis → 法语 fatal／拉丁直接借入','命中注定的；致命的'],['英语 fatal','引起死亡或导致不可挽回失败的']]
INF=S+[['拉丁 in- + fāns → īnfāns〔宾格 īnfantem〕','不 + 正在说话的 → 还不会说话的孩子'],['中古英语 infaunt → 英语 infant','婴儿、幼儿']]
ARMY=INF[:2]+[['意大利语或西班牙语 infante → infanteria','儿童、年轻人 → 地位或资历较低的步兵 → 步兵集体'],['法语 infanterie → 英语 infantry','步兵、步兵部队']]
CONF=[['拉丁 fatērī','承认、表明；与 fārī“说”相关'],['拉丁 con- + fatērī → confitērī，分词 confessus','坦承、承认'],['古法语 confesser → 中古英语 confessen → 英语 confess','说出自己隐瞒或不愿承认的事']]
CONFESS=CONF[:2]+[['拉丁 confessiō → 古法语 confession','承认、坦白这一行为'],['中古英语 confessioun → 英语 confession','坦白、认罪；宗教中的告解或信仰宣认']]
PRO=CONF[:1]+[['拉丁 pro- + fatērī → profitērī，分词 professus','公开说出、宣称'],['中古英语 professen → 英语 profess','法语／拉丁借入与从 profession 逆构两种路线分析；公开声称']]
FAB=S+[['拉丁 fābula → 古法语 fable','说出的故事、叙述'],['中古英语 fable → 英语 fable','寓言；也可泛指虚构的故事']]
FABS=S+[['拉丁 fābula → fābulōsus','故事 → 属于故事或传说的'],['中古英语 fabulous／fabulose → 英语 fabulous','传说般非凡的；口语中极好的']]
AFF=S+[['拉丁 ad- + fārī → affārī → affābilis','向人说话 → 容易交谈、亲切的'],['法语 affable → 英语 affable','亲切随和、让人好开口的']]
INEF=S+[['拉丁 ex- + fārī → effārī → effābilis','说出来 → 可以说出的'],['拉丁 in- + effābilis → ineffābilis → 法语及英语 ineffable','说不出来的；难以言表的']]
W=[
E('famous','/ˈfeɪməs/','著名的；有名的','很多人都在谈论、都听说过，于是名字传开了。','经法语 famous 接拉丁 fāmōsus，源于 fāma“传闻、声誉”。现代可与 fame + -ous 对照，历史上是完整形容词借入。',FAMOUS,'be famous for 后面放出名的原因，be famous as 后面放身份。出名与能力强不是一回事：famous 首先说公众知道这个人或东西。','be famous for its food；be famous as a writer；a famous landmark。','famous 一般是中性或褒义的知名；infamous 专门说恶名或不光彩的知名。',('The town is famous for its handmade pottery.','这座小镇以手工陶器闻名。'),('She became famous as a writer of detective stories.','她作为侦探小说作家出了名。')),
E('fate','/feɪt/','命运；结局；注定的遭遇','好像某个结果早已被说定，人最终走到那个结局。','拉丁 fātum 是 fārī“说”的分词名词用法，可指预言、神谕或命运；进入英语后保留了“结果已定”的感觉。',FATE,'相信 fate 是相信某种注定；ask about the fate of a missing ship 则只是问那艘船最终怎样了。单词不要求说话人真的相信神秘力量。','leave something to fate；the fate of a project；meet one’s fate。','destiny 常带人生方向或宏大使命感；fate 更容易用于不由自己控制的结局，也可以很中性。',('The final vote will decide the fate of the project.','最后的投票将决定这个项目的命运。'),('She refused to leave her future entirely to fate.','她不愿把自己的未来完全交给命运。')),
E('fame','/feɪm/','名声；知名度','你的名字被不断提起，渐渐成了大家都知道的名字。','经法语 fame 接拉丁 fāma“传闻、说法、声誉”，与 fārī“说话”同族；不是从 famous 删除词尾才形成。',FAM,'achieve fame 是成名；fame can fade 是知名度会消退。现代 fame 多指广为人知的名气，若强调品行口碑好坏，reputation 更合适。','rise to fame；achieve fame；international fame；a claim to fame。','fame 强调有多少人听说过；reputation 强调人们怎样评价。一个人很有名，口碑仍可能很差。',('The song brought her international fame.','这首歌让她在国际上成名。'),('He valued a quiet life more than fame.','比起名气，他更珍惜平静的生活。')),
E('fabulous','/ˈfæbjələs/','极好的；令人惊叹的；传说中的','好得像故事里才有；早期也可以真的指故事、神话中的东西。','借拉丁 fābulōsus，接 fābula“故事”；现代可看作 fable 与 -ous 对应，但不是从“著名”直接发展来的词。',FABS,'日常 That’s fabulous! 是强烈赞赏，不是在怀疑真假。较正式的 fabulous creatures 则可能真指龙、怪兽等传说生物。','a fabulous meal；fabulous views；fabulous wealth；fabulous creatures。','fabulous 可表示极好，也可表示传说的；famous 只说出名，两者别因开头相似混淆。',('We had a fabulous meal overlooking the harbour.','我们一边俯瞰港口，一边享用了一顿极棒的饭。'),('The manuscript contains drawings of fabulous creatures.','手稿里画着各种传说中的生物。')),
E('infant','/ˈɪnfənt/','婴儿；幼儿；初期的','最初的画面是一个还不会说话的小孩子。','拉丁 in-“不” + fāns“正在说话的”组成 īnfāns，词形 īnfant- 进入英语。这里的 in- 不是“里面”。',INF,'日常指很小的孩子；具体年龄范围会随医疗、法律或学校语境变化。an infant industry 则把新兴行业比作刚开始成长的孩子，并不是行业真的不会讲话。','an infant’s sleep；infant care；an infant industry。','baby 日常范围更灵活；infant 比较正式。词源的“不会说话”帮助记忆，但不是现代判断年龄的唯一标准。',('The infant slept in a cot beside the bed.','婴儿睡在床边的小床里。'),('The report discusses support for an infant industry.','报告讨论了对一个新兴产业的支持。')),
E('infantry','/ˈɪnfəntri/','步兵；步兵部队','从年轻、低资历的随从，发展到以徒步作战为基本角色的士兵群体。','经法语 infanterie，接意大利语或西班牙语 infanteria；其中 infante 曾指年轻人和步兵，远接拉丁 īnfāns。不是 infant + tree，更不是婴儿组成的军队。',ARMY,'步兵可以乘车、乘直升机抵达，并非行军全过程都得走路。词强调战斗角色；现代也有机械化步兵。','an infantry unit；an infantry battalion；mechanized infantry。','cavalry 原指骑兵；infantry 指步兵。历史名称常继续保留，不能只凭现代交通工具判断兵种。',('The infantry crossed the river after the engineers secured the bridge.','工兵确保桥梁安全后，步兵渡过了河。'),('The museum explains how infantry equipment changed over time.','博物馆介绍了步兵装备随时间的变化。'),sources=['https://www.etymonline.com/word/infantry']),
E('confession','/kənˈfeʃən/','坦白；供认；告解；信仰宣认','把一直藏着的事，或自己所信的东西，明确说出来。','拉丁 confessiō 经法语独立借入；现代可拆 confess + -ion，但不是只有英语动词加后缀这一条历史路线。',CONFESS,'a confession of guilt 是认罪；宗教里的 confession 也可说向神父告解，或正式陈述信仰。口语 I have a confession to make 常只是“我得坦白一件事”，未必真犯了罪。','make a confession；a written confession；a confession of faith。','admission 可承认任何事实；confession 常带此前隐瞒、羞于承认或宗教表明的色彩。',('I have a confession to make: I ate the last piece of cake.','我得坦白：最后一块蛋糕是我吃的。'),('The detective recorded the suspect’s confession.','侦探记录了嫌疑人的供认。')),
E('confess','/kənˈfes/','坦白；承认；忏悔','本来不想说或一直没说，现在开口承认了。','古法语 confesser 接拉丁 confitērī 的分词词干 confess-；con- 与 fatērī“承认”组合。现代不必把 con- 硬译成“和别人一起”。',CONF,'confess to doing something 里的 to 是介词，要接 doing。I must confess that… 可以温和地承认一件小事，如没听懂或不喜欢某部电影。','confess to a crime；confess to taking something；confess that…；confess to someone。','admit 通常更中性；confess 更突出这件事此前难以启齿。confess 不表示证据已经证明一切，仍是“某人承认”。',('He confessed to breaking the window.','他承认打碎了窗户。'),('I must confess that I did not understand the ending.','我得承认，我没看懂结尾。')),
E('famed','/feɪmd/','以……闻名的；著名的','名气已经传开，常接着说明究竟因什么出名。','由 fame 的 -ed 形式形成形容词，联系使之出名的旧动词用法。-ed 读 /d/，不是另加一个音节。',FAM+[['英语 fame → famed','有名声的、闻名的']],'常见 be famed for：讲一个地方的美食、人物的技艺等。它与 famous 很接近，但 famed 的文气通常更强，也很爱接 for 交代特色。','be famed for；a famed artist；a restaurant famed for its seafood。','famed 与 famous 都是有名；fame 是名词。不要把 famed 当成“曾经有名、现在不有名”的必然标志。',('The village is famed for its colourful autumn markets.','这个村庄以热闹多彩的秋季集市闻名。'),('A famed violinist led the masterclass.','一位著名小提琴家主持了大师课。')),
E('preface','/ˈprefəs/','前言；序；在……之前先说','正文还没开始，作者先站出来交代几句。','拉丁 prae-“在前” + fārī“说”形成 praefātiō，经中世纪拉丁 praefātia、法语 preface 进入英语。后半段不是 face“脸”。',S+[['拉丁 prae- + fārī → praefātiō → 中世纪拉丁 praefātia','预先说的话'],['古法语 preface → 中古英语 preface → 英语 preface','正文前的说明；作动词表示先作铺垫']],'书的 preface 常讲为什么写、怎样写、谁提供了帮助。动词 preface A with B 是先用 B 给 A 作开场，不是把 B 放到最后。','in the preface；write a preface；preface a remark with an apology。','foreword 常由别人为书写；preface 通常由作者本人写。introduction 更常直接引入主题内容，实际书籍也可能交叉使用。',('The author explains her research method in the preface.','作者在前言里介绍了研究方法。'),('He prefaced his question with a brief explanation.','提问前，他先作了简短说明。')),
E('defamation','/ˌdefəˈmeɪʃən/','诽谤；损害名誉的言论','让损害一个人声誉的说法传出去。','经法语 diffamacion 接拉丁 diffāmātiō；现代可与 defame + -ation 对照，名词本身有独立借入路线。',FAM[:1]+[['拉丁 diffāmāre → diffāmātiō → 古法语 diffamacion','传播有损声誉的说法 → 这种行为'],['英语 defamation','诽谤、名誉损害']],'法律语境通常涉及被当成事实传播的不实说法及名誉损害，具体构成随司法辖区而异。不是一句难听话或一次负面评价就自动构成 defamation。','a defamation claim；sue for defamation；alleged defamation。','libel 通常偏书面或记录形式，slander 通常偏口头；defamation 是更宽的总称。',('She brought a defamation claim over the false allegations.','她针对那些虚假指控提起了诽谤诉讼。'),('The workshop explains the difference between criticism and defamation.','研讨课解释了批评与诽谤的区别。'),sources=['https://en.wiktionary.org/wiki/defamation#English','https://www.law.cornell.edu/wex/defamation']),
E('infancy','/ˈɪnfənsi/','婴儿期；发展初期','像婴儿一样，已经开始存在，但还处在很早的成长阶段。','中古英语 infancie 接拉丁 īnfantia；现代可对应 infant + -cy，不能只按英语新派生画历史。',INF[:2]+[['拉丁 īnfantia → 中古英语 infancie → 英语 infancy','幼小的阶段；引申为事物的发展早期']],'in its infancy 特别常用来形容技术、项目或学科尚未成熟。它不等于“毫无价值”，只是现阶段还早，能力和规则可能都在形成。','during infancy；from infancy；a technology in its infancy。','childhood 范围比 infancy 广；early stage 是更中性的早期表达，不带婴儿成长的比喻。',('The photographs show her brother from infancy to adolescence.','这些照片记录了她弟弟从婴儿期到青春期的成长。'),('Research into the material is still in its infancy.','对这种材料的研究还处于起步阶段。')),
E('fable','/ˈfeɪbəl/','寓言；虚构故事','把一个道理放进小故事里，让人物、动物替你演出来。','拉丁 fābula 是 fārī“说”的同族故事名词，经古法语 fable 进入英语；最初范围比现代“寓言”宽。',FAB,'典型 fable 让动物说话、做选择，最后显出一个道理，但不是每篇都必须有动物。另一些语境里 fable 只表示不可信的故事或传说，要看上下文。','Aesop’s fables；a moral fable；the lesson of a fable。','fairy tale 常有魔法或神奇情节；fable 更常用简短故事表达生活道理。',('The fable uses a greedy fox to show the cost of dishonesty.','这则寓言用一只贪婪的狐狸表现不诚实的代价。'),('The teacher asked the class to write a fable with a clear moral.','老师让全班写一则道理明确的寓言。')),
E('fateful','/ˈfeɪtfəl/','影响重大的；决定命运的','看似一个普通时刻，却把后来的人生或事情带向了另一条路。','fate + -ful；表示充满命运影响，并不等于 fatal“致命”。',FATE+[['英语 fate + -ful → fateful','对后来的结局有重大影响']],'a fateful meeting 可能促成一生的合作，也可能引发灾难。这个词常在回顾时出现，因为当时的人未必知道那一刻会怎样改变未来。','a fateful decision；a fateful day；a fateful encounter。','fateful 强调后果重大；fatal 强调死亡或不可挽回的失败。重大不一定坏，更不一定死人。',('That fateful meeting began a partnership that lasted thirty years.','那次改变命运的相遇开启了一段持续三十年的合作。'),('She later regretted the fateful decision to ignore the warning.','她后来后悔作出了无视警告的重大决定。')),
E('nefarious','英 /nɪˈfeəriəs/；美 /nɪˈferiəs/','邪恶的；恶毒的；不法的','不是普通失误，而是带着坏心思、做法也恶劣。','借拉丁 nefārius，来自 ne-“不” + fās“神圣规范、正当之事”；fās 通常联系 fārī 所表达的神圣宣令。不要按英语 near 或 far 拆。',S+[['拉丁 fās → nefās → nefārius','神圣认可的规范 → 违背规范的恶行 → 邪恶的'],['英语 nefarious','恶毒、不法的，语气较强且较书面']],'常修饰 schemes、activities、purposes，像小说中暗藏的阴谋。也可以故意夸张地开玩笑，但严肃使用时比 naughty 重得多。','a nefarious scheme；nefarious activities；for nefarious purposes。','illegal 只判断是否违法；nefarious 还带强烈的道德谴责，通常暗示恶意。',('The villain’s nefarious scheme depended on stealing the city’s water supply.','反派的邪恶计划要靠窃取城市供水来实现。'),('The report traced the money to a network of nefarious activities.','报告追查到这笔钱与一系列不法活动有关。'),sources=['https://www.etymonline.com/word/nefarious']),
E('profess','/prəˈfes/','公开声称；表明信仰或感情','把“我相信什么、我是什么、我会什么”公开说出来。','有法语／拉丁借入分析，也有从较早的 profession 逆构的分析；远接拉丁 profitērī，pro- 有公开意味，fatērī 是表明、承认。',PRO,'profess love 表白爱意；profess ignorance 声称自己不知情。有时说话人保留疑问：他这么说，不代表行为已证明真是如此。','profess to know；profess ignorance；profess a belief；profess one’s love。','confess 常承认原先不愿说的事实；profess 常主动公开表明立场、信念或身份。',('He professed to know nothing about the missing documents.','他声称对文件失踪一事一无所知。'),('She professed a deep admiration for her former teacher.','她公开表达了对以前老师的深深敬佩。'),sources=['https://www.etymonline.com/word/profess','https://en.wiktionary.org/wiki/profess#English']),
E('infamy','/ˈɪnfəmi/','恶名；臭名；恶行带来的耻辱','被大家谈论，却是因为做了坏事而留下坏名声。','拉丁 īnfāmia 经古法语 infamie 借入；其基础是 in-“不”与 fāma“声誉”构成的 īnfāmis，形成失去好名声的意思。',FAM[:1]+[['拉丁 īnfāmis → īnfāmia → 古法语 infamie','声誉败坏的 → 恶名'],['中古英语 infamie → 英语 infamy','臭名、耻辱']],'rise to fame 是出名，gain infamy 则是留下臭名。不是简单“没人知道”：infamy 往往恰恰很出名，只是名声很坏。','gain infamy；live in infamy；a name associated with infamy。','anonymity 是身份不为人知；infamy 是身份广为人知而评价恶劣。',('The prison gained infamy for its brutal conditions.','这座监狱因残酷的关押条件而臭名昭著。'),('His name became a symbol of infamy in the town.','他的名字在镇上成了恶名的象征。')),
E('infantile','/ˈɪnfəntaɪl/；美亦 /ˈɪnfəntəl/','婴幼儿的；幼稚的','本来是婴儿年龄的特点；用在成年人身上，就说他表现得没长大。','借拉丁 īnfantīlis“婴儿的”；现代可对应 infant + -ile，但历史上已有完整拉丁形容词。',INF[:2]+[['拉丁 īnfantīlis → 英语 infantile','属于婴儿的；后来引申为成年人幼稚不成熟']],'医学或发育语境中 infantile 可以是中性的年龄说明。an infantile argument 才是批评，觉得争论幼稚。把婴儿描述词用于成年人时，评价方向就变了。','infantile behaviour；infantile humour；infantile development。','childlike 可以赞美纯真；infantile 的比喻义通常批评不成熟，不能随意替换。',('His infantile jokes annoyed everyone at the meeting.','他那些幼稚的玩笑惹恼了会上所有人。'),('The chapter describes patterns of infantile sleep.','这一章描述了婴幼儿的睡眠模式。')),
E('affable','/ˈæfəbəl/','和蔼的；随和的；好交谈的','你很容易走过去开口，对方让你觉得舒服、不拘束。','拉丁 ad- + fārī 形成 affārī“向人说话”，再有 affābilis“容易交谈的”，经法语 affable 借入。不是 a + fable“一个寓言”。',AFF,'affable host 会主动打招呼、自然聊天，不让客人紧张。它说的是待人接物的亲切，不要求这个人毫无原则或事事答应。','an affable manner；an affable host；friendly and affable。','agreeable 可说令人愉快或愿意同意；affable 特别突出交谈和接近时的亲切感。',('Our host was affable and made everyone feel welcome.','主人亲切随和，让每个人都感到受欢迎。'),('Despite his senior position, he remained affable and easy to approach.','尽管职位很高，他仍然和蔼可亲、容易接近。')),
E('infantryman','英 /ˈɪnfəntrimən/；美 /ˈɪnfəntrimən/','步兵；步兵士兵','步兵部队里的一个人，视角从兵种整体落到个人。','infantry + man；复数 infantrymen 中 man 变 men，重音仍落在前部。',ARMY+[['英语 infantry + man → infantryman','步兵中的士兵']],'历史叙述和军事语境中常见；若不需性别色彩，也可以说 infantry soldier。不要误解成“带孩子的人”，尽管 infantry 的远源确与年轻人相联。','a young infantryman；an infantryman’s equipment；infantrymen on patrol。','infantry 是部队或兵种的集合名称；infantryman 是其中一名士兵。',('The young infantryman carried a letter from home in his pocket.','那个年轻步兵口袋里装着一封家书。'),('The diary records an infantryman’s daily life during the campaign.','日记记录了一名步兵在战役期间的日常生活。'),sources=['https://www.etymonline.com/word/infantryman']),
E('ineffability','/ɪˌnefəˈbɪləti/','难以言表；不可言说性','感受已经有了，语言却好像装不下它。','现代可看作 ineffable + -ity，-able 对应为 -ability；另有直接联系拉丁 ineffābilitās 的借入分析。',INEF[:-1]+[['拉丁 ineffābilis／ineffābilitās；英语 ineffable + -ity','拉丁名词借入与英语派生两种分析'],['英语 ineffability','无法充分用语言表达的性质']],'常出现在哲学、宗教和艺术讨论中，问某种经验能否被完整说出。不是“不会说英语”的语言障碍，而是觉得任何说法都不够。','the ineffability of experience；a sense of ineffability；discuss ineffability。','inexpressibility 也指难表达，较直白；ineffability 常带深刻、神秘或超出语言的意味。',('The essay explores the ineffability of profound grief.','这篇文章探讨了深重悲痛为何难以言表。'),('For the poet, the ineffability of the experience was part of its beauty.','对诗人来说，这种体验难以言表，本身就是其美的一部分。'),sources=['https://www.etymonline.com/word/ineffability','https://en.wiktionary.org/wiki/ineffability#English','https://www.merriam-webster.com/dictionary/ineffability']),
E('bifarious','英 /baɪˈfeəriəs/；美 /baɪˈferiəs/','双重的；两种方式的；两列的〔罕用〕','同一个东西分成两面、两路或两排来呈现。','确定的近源是拉丁 bifāriam“以两种方式”与 bifārius。-fariam 的远源有分歧：一种联系 fārī“说”，另一种联系“放置”的印欧词根；不把前者当定论。',[['拉丁 bifāriam → bifārius','以两种方式 → 双重的；-fariam 远源有不同分析'],['英语 bifarious','双重、两义；植物形态中也可说两列排列']],'这是罕见词，日常通常用 twofold 或 in two rows。若用在旧文本的 prophecy，可表示有两种解释；植物描述则可能是叶片分成两列，不是植物在“说两遍”。','a bifarious arrangement；bifarious leaves；a bifarious interpretation。','bifarious 不等于 bilingual“双语的”。即使采纳“说”的词源解释，现代也不专指两种语言。',('The old commentary describes the prophecy as bifarious, allowing two readings.','旧注释称这则预言具有双重含义，可以有两种解读。'),('The botanical description notes a bifarious arrangement of the leaves.','植物学描述指出叶片呈两列排列。'),sources=['https://www.etymonline.com/word/bifarious','https://www.merriam-webster.com/dictionary/bifarious','https://en.wiktionary.org/wiki/bifarious#English'])
]
PROFESSION=PRO[:2]+[['拉丁 professiō → 古法语 profession → 中古英语 professioun','公开声明，早期常指宗教誓言'],['英语 profession','专业职业；也保留公开表白、宣认的意思']]
W.extend([
E('famously','/ˈfeɪməsli/','众所周知地；极好地','说话人提醒你：这一点大家早就知道；另有“好极了”的旧式口语用法。','famous + -ly；名声从“有多少人知道”转为对整件事的提示。',FAMOUS+[['英语 famous + -ly → famously','众所周知地；也可表示非常顺利、融洽']],'famously shy 的重点不是“害羞得很出名地做动作”，而是这个人害羞是出了名的。get on famously 则是相处极好，不是两个人一起成名。','famously difficult；famously private；get on famously。','famously 强调已经广为人知；fabulously 常加强“好得惊人”的程度。',('The chef is famously strict about fresh ingredients.','这位主厨对新鲜食材的严格要求是出了名的。'),('The two new colleagues got on famously from their first day.','两位新同事从第一天起就相处得非常融洽。')),
E('fabulously','/ˈfæbjələsli/','极其；好得惊人地；传说般地','像故事里才会有的程度，常用于强烈赞美或夸张。','fabulous + -ly；从“传说般的、极好的”变成程度或方式副词。',FABS+[['英语 fabulous + -ly → fabulously','以令人惊叹的程度或方式']],'fabulously wealthy 是富得惊人；a fabulously good meal 是好吃极了。通常不是认真说财富或饭菜不存在，只是把程度往上推。','fabulously rich；fabulously expensive；fabulously well。','famously wealthy 是出了名地有钱；fabulously wealthy 是有钱到惊人的程度。',('The hotel is beautiful but fabulously expensive.','这家酒店很漂亮，但贵得惊人。'),('The costumes were fabulously colourful.','服装的色彩绚丽极了。')),
E('infamous','/ˈɪnfəməs/','臭名昭著的；声名狼藉的','名字传得很广，传开的却是坏事。','中古英语借中世纪拉丁 īnfāmōsus，接拉丁 īnfāmis“坏名声的”；表面可看 in- + famous，但意义不是普通的“不出名”。',FAM[:1]+[['拉丁 īnfāmis → 中世纪拉丁 īnfāmōsus','失去好声誉、声名狼藉的'],['中古英语 enfamouse 等 → 英语 infamous','因坏事出名的']],'an infamous fraud 是臭名昭著的骗子；an infamous decision 是广受指责的决定。famous 的 /feɪ/ 在这里变为弱读 /fə/，别照着 in + famous 生硬读。','be infamous for；an infamous scandal；an infamous prison。','unknown 是不知名；infamous 是恶名远扬。in- 在这里的历史作用不允许机械翻成“没有知名度”。',('The company became infamous for selling fake medicines.','这家公司因销售假药而臭名昭著。'),('The book investigates an infamous political scandal.','这本书调查了一桩臭名昭著的政治丑闻。')),
E('infamously','/ˈɪnfəməsli/','臭名昭著地；以糟糕表现出名地','强调接下来的坏特点，已经坏到大家都知道。','infamous + -ly；副词保留坏名声的评价。',FAM[:1]+[['拉丁 īnfāmis／īnfāmōsus → 英语 infamous','有恶名的'],['英语 infamous + -ly → infamously','以坏事或糟糕特点闻名地']],'infamously unreliable 是不可靠得出了名。日常也会把不太严重的麻烦夸张地说成 infamously difficult，并不总指犯罪。','infamously unreliable；infamously difficult；infamously corrupt。','famously 本身可褒可中性；infamously 把负面评价直接放进副词。',('The train service is infamously unreliable in winter.','这条列车线路冬季运行不可靠，是出了名的。'),('The exam includes an infamously difficult final question.','这场考试有一道出了名难的最后一题。')),
E('defame','/dɪˈfeɪm/','诽谤；败坏名誉','把损害别人口碑的说法散布出去。','经盎格鲁法语 defamer 接拉丁 diffāmāre，基础是 fāma“传闻、声誉”；拉丁 dis- 有散布意味，后来形成损害声誉的常用义。',FAM[:1]+[['拉丁 diffāmāre → 盎格鲁法语 defamer','传扬名声或说法；败坏名声'],['中古英语 defamen → 英语 defame','诽谤、损害他人名誉']],'现代常涉及不实指控，让别人因此看坏某个人。并不是只要说了负面事实就一定叫 defame；法律使用还涉及具体条件。','defame someone；an attempt to defame；defame someone’s character。','criticize 是批评，可能有事实依据；defame 强调以损害名誉的说法攻击他人，语气和后果更重。',('She accused the website of trying to defame her with fabricated stories.','她指责该网站试图用编造的故事诽谤她。'),('The editor removed the unsupported allegation because it could defame an innocent person.','编辑删去了没有依据的指控，因为它可能诽谤一个无辜的人。'),sources=['https://en.wiktionary.org/wiki/defame#English','https://www.law.cornell.edu/wex/defamation']),
E('defamatory','英 /dɪˈfæmətri/；美 /dɪˈfæmətɔːri/','诽谤性的；损害名誉的','这句话或这篇文章会让别人对某人的品行、行为形成坏判断。','经法语 diffamatoire 接中世纪拉丁 diffāmātōrius；英语形式受 de- 影响。现代与 defame 对应，不能只凭相似就说是英语后缀新造。',FAM[:1]+[['拉丁 diffāmāre → 中世纪拉丁 diffāmātōrius → 法语 diffamatoire','损害声誉 → 有这种性质的'],['英语 defamatory','带有诽谤或名誉损害性质的']],'常修饰 statement、article、allegation，重点在言论内容。说“被指为 defamatory”不等于已经被法院认定；例句的 alleged、potentially 不能随手删掉。','a defamatory statement；defamatory allegations；potentially defamatory material。','offensive 是冒犯、令人不快；defamatory 是损害名誉，两者不能画等号。',('The publisher withdrew the article after receiving a complaint about defamatory statements.','出版方收到有关诽谤性言论的投诉后撤下了文章。'),('The lawyer reviewed the draft for potentially defamatory allegations.','律师检查了草稿中可能构成诽谤的指控。'),sources=['https://en.wiktionary.org/wiki/defamatory#English','https://www.law.cornell.edu/wex/defamation']),
E('ineffable','/ɪˈnefəbəl/','难以言表的；不可言说的','心里知道那种感受，但怎么说都觉得说不全。','拉丁 in-“不” + effābilis“可说出的”；effābilis 接 ex- + fārī。经法语或直接从拉丁借入，不是 in- 加 affable。',INEF,'常修饰 joy、beauty、sadness 等很深的感受，也用于宗教中的不可言说。它说的是语言不够，不是对方不愿意与你交谈。','ineffable joy；ineffable beauty；an ineffable sense of loss。','affable 是人好交谈；ineffable 是事物难表达。两个词都联系“说”，否定结构却不同。',('She felt an ineffable joy when she heard the child laugh.','听到孩子笑时，她感到一种难以言表的喜悦。'),('There was something ineffable about the silence of the mountains.','群山的寂静中有一种难以言传的意味。'),sources=['https://www.etymonline.com/word/ineffable']),
E('affability','/ˌæfəˈbɪləti/','和蔼；亲切随和','一种让别人愿意靠近、放心开口的待人方式。','借法语 affabilité，与 affable 同族；现代可对应 affable + -ity，-able 变为 -ability。名词不是只在英语内部派生。',AFF[:2]+[['法语 affable → affabilité → 英语 affability','容易交谈的 → 亲切随和这一品质']],'affability 常从笑容、倾听、随和聊天中体现。它不是“凡事同意”：一个人可以亲切地拒绝，也可以不亲切地答应。','natural affability；a reputation for affability；warmth and affability。','politeness 可以保持距离，只做到有礼貌；affability 更有亲切、容易交谈的感觉。',('Her natural affability helped the new students feel at ease.','她天生的亲和力让新生感到自在。'),('His affability did not prevent him from making firm decisions.','他的和蔼并不妨碍他作出坚定的决定。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/affability','https://www.etymonline.com/word/affability']),
E('affably','/ˈæfəbli/','和蔼地；亲切随和地','开口说话时给人留出空间，让交谈自然、舒服。','affable + -ly；词尾 -le 在副词中变成 -ly。',AFF+[['英语 affable + -ly → affably','以亲切、好交谈的方式']],'常修饰 greet、chat、smile、reply，描述人与人接触时的态度。重点不在声音小，而在没有架子、容易亲近。','greet someone affably；chat affably；reply affably。','softly 是声音轻；affably 是态度亲切。一个人可以声音很响但很随和。',('The librarian greeted us affably and asked what we were looking for.','图书管理员亲切地招呼我们，询问我们在找什么。'),('He chatted affably with the passengers while they waited.','等候时，他和乘客们轻松亲切地聊着天。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/affably','https://www.etymonline.com/word/affable']),
E('profession','/prəˈfeʃən/','专业职业；行业；公开表白或宣认','先是公开说“我信奉、我从事这个”，后来指以专门知识从事的职业。','拉丁 professiō 经法语进入英语，早于英语 profess；现代虽能按 profess + -ion 记忆，历史不能反过来只画英语派生。',PROFESSION,'the medical profession 可以指医学职业，也可以指整个医务专业群体。a profession of faith 则保留公开表明信仰的意思，不是在说一份工作。','by profession；enter a profession；the legal profession；a profession of faith。','job 是具体工作岗位；profession 常强调需要专门训练的职业领域，也有表白、宣认的旧义。',('She is an architect by profession.','她的职业是建筑师。'),('The ceremony included a public profession of faith.','仪式包括公开的信仰宣认。'),sources=['https://www.etymonline.com/word/profession']),
E('professional','/prəˈfeʃənəl/','职业的；专业的；符合职业标准的；专业人士','把某件事作为职业来做，或做得符合这份职业应有的标准。','profession + -al 的对应在中古英语已有形式；早期宗教职业背景，后来扩展到专业工作和以此谋生的活动。',PROFESSION[:-1]+[['中古英语 profession 相关形容词 professhennalle → 英语 professional','职业的；按专业规范做事的']],'a professional player 是以打球为职业；a professional manner 是做事负责得体。两义不能混成一个：拿工资不自动保证做得专业，业余者也可能有很高水准。','professional advice；a professional musician；professional conduct；hire a professional。','amateur 常指非以此谋生，不必表示技术差；professional 可以说职业身份，也可以评价做事标准。',('She became a professional photographer after years of practice.','练习多年后，她成了职业摄影师。'),('He handled the complaint in a calm and professional manner.','他冷静、专业地处理了投诉。'),sources=['https://en.wiktionary.org/wiki/professional#English','https://www.etymonline.com/word/professional']),
E('professor','英 /prəˈfesə/；美 /prəˈfesər/','教授；大学教师〔依地区和语境〕','原来是公开表明自己掌握某门知识、并把它教授给别人的人。','拉丁 professor 从 profitērī 一系形成，经过法语或直接借入英语；现代可看 profess + -or，但不是单从英语动词新造。',PRO[:2]+[['拉丁 professor → 法语 professeur／拉丁直接路线','声称具备专门知识并授课的人'],['中古英语 professour → 英语 professor','大学教师或教授职称']],'不同教育制度里称呼范围不同：有的语境指明确的高级职称，有的尤其美式语境可泛称大学授课教师。不能把每个 school teacher 都称为 professor。','a professor of history；Professor Chen；an assistant professor；a full professor。','teacher 是广义教师；professor 通常属于高等教育，并可能是一项正式学术职称。',('The professor asked us to defend our interpretation with evidence.','教授要求我们用证据支持自己的解读。'),('Professor Chen teaches a course on the history of science.','陈教授教授一门科学史课程。'),sources=['https://www.etymonline.com/word/professor']),
E('professed','/prəˈfest/','公开声称的；自称的；宣誓入会的','这是一种说出来的信念或身份，至于行动是否吻合，还要另看。','profess 的过去分词转为形容词；-ed 在 /s/ 后读 /t/。',PRO+[['英语 profess → professed','被公开表明的；宗教中可指已立誓的']],'his professed concern 是他口头表达的关切，有时带一点怀疑，也可以只是中性叙述。a professed member of a religious order 另指已经作出宗教誓愿的成员。','professed beliefs；a professed supporter；professed concern。','professed 说公开宣称；proven 才说已经证实。不要把声称与事实验证混为一谈。',('Her actions were consistent with her professed beliefs.','她的行动与她公开表明的信念一致。'),('Despite his professed concern, he offered no practical help.','尽管他声称关心，却没有提供任何实际帮助。')),
E('confessional','/kənˈfeʃənəl/','自我坦白式的；宗派信仰的；告解室','把私密经验说出来；宗教里也可以指明确的信仰归属，或告解的场所。','形容词有中世纪拉丁 confessiōnālis 的借入分析，现代可对应 confession + -al；告解室名词另经法语 confessionnal 接中世纪拉丁 confessionale。',CONF[:2]+[['中世纪拉丁 confessiōnālis → 英语形容词；confessionale → 法语 confessionnal → 英语名词','有关告白、信仰的；供告解使用的场所'],['英语 confessional','自我揭露式的；宗派的；告解室']],'confessional poetry 把私人创伤、家庭生活等放进作品中，不等于每句都是法庭供词。a confessional 则常是教堂内进行告解的小隔间或场所。','confessional writing；a confessional tone；enter the confessional。','confession 是坦白或告解的内容、行为；confessional 作名词常说场所，作形容词也可说写作风格。',('The memoir has an intimate, confessional tone.','这本回忆录带有亲密、自我坦白式的语气。'),('A small confessional stood beside the chapel entrance.','小礼拜堂入口旁有一间小告解室。'),sources=['https://www.etymonline.com/word/confessional','https://en.wiktionary.org/wiki/confessional#English']),
E('confessor','英 /kənˈfesə/；美 /kənˈfesər/；宗教称号亦英 /ˈkɒnfesə/','听告解的神父；坦白者；宣信者','这个词围绕告白，却可能指说的人，也可能指宗教中听告解的人。','拉丁 confessor 接 confitērī，经盎格鲁法语 confessour 进入英语；现代可对应 confess + -or。',CONF[:2]+[['拉丁 confessor → 盎格鲁法语 confessour','公开承认或宣认信仰的人'],['中古英语 confessor → 英语 confessor','坦白者；亦指听告解的神父，或受迫害而未殉道的宣信者']],'a priest as her confessor 通常说听她告解、作宗教指导的神父。历史圣徒称号中的 Confessor 则强调坚持宣认信仰，不是说这位圣徒承认犯了罪。','a spiritual confessor；speak to one’s confessor；a Christian confessor。','confessor 的 -or 看似只指动作执行者，实际宗教义也包含接受告解的人，不能机械套“认罪者”。',('She sought advice from her confessor before making the decision.','作决定前，她向听她告解的神父寻求了建议。'),('The historian explained why the saint was honoured as a confessor rather than a martyr.','历史学家解释了为什么这位圣徒被尊为宣信者，而非殉道者。'),sources=['https://en.wiktionary.org/wiki/confessor#English']),
E('fatal','/ˈfeɪtəl/','致命的；造成毁灭性失败的','不只是让事情变差，而是把生命或一项事业推向终结。','法语或拉丁 fātālis 借入，接 fātum“命运”；从命中注定、毁灭性的意味发展出常见的致命义。现代可与 fate + -al 对照。',FATAL,'a fatal accident 有人因此死亡；a fatal flaw 是足以毁掉方案的缺陷。计算机的 fatal error 可能导致程序无法继续，不是在说机器有生命。','a fatal injury；a fatal mistake；a fatal flaw；prove fatal。','serious 只是严重；fatal 在字面义中已经涉及死亡，在比喻义中则导致彻底失败。',('The collision caused two fatal injuries.','碰撞导致两人因伤死亡。'),('The proposal contained a fatal flaw in its cost estimates.','提案的成本估算存在一个致命缺陷。'),sources=['https://www.etymonline.com/word/fatal']),
E('fatally','/ˈfeɪtəli/','致命地；不可挽回地','某个伤害或缺陷直接把结果推向死亡或彻底失败。','fatal + -ly；副词修饰伤害或破坏的程度、后果。',FATAL+[['英语 fatal + -ly → fatally','以致命或毁灭结果的方式']],'fatally injured 明确说伤势造成死亡，不只说伤得重。fatally flawed plan 是根本缺陷让计划行不通，属于比喻用法。','fatally injured；fatally wounded；fatally flawed；fatally undermine。','badly 只是程度很重；fatally 还说结果到了终结或不可挽回的地步。',('The driver was fatally injured in the crash.','司机在事故中受伤身亡。'),('The missing evidence fatally weakened the prosecution’s case.','关键证据的缺失使控方的案子受到致命削弱。')),
E('fatality','英 /fəˈtæləti/；美 /fəˈtæləti/，亦 /feɪˈtæləti/','死亡事故；死亡人数中的一人；死亡','把致命后果作为一次事件或一个死亡个案来统计。','经法语 fatalité 接后期拉丁 fātālitās，源于 fātālis；现代可与 fatal + -ity 对照，重音转到第二音节。',FATE[:2]+[['拉丁 fātālis → 后期拉丁 fātālitās → 法语 fatalité','命运所定、致命的 → 相应的性质和结果'],['英语 fatality','现代常指意外、灾害等造成的死亡或死亡者']],'three fatalities 通常表示三人死亡，不是三个受伤者。fatality rate 是死亡所占的比率，谈具体数据时必须看分母是什么。','road fatalities；report a fatality；a fatality rate。','casualty 可以包含伤者和死者；fatality 在此类统计中专指死亡，不可混算。',('The fire caused several injuries but no fatalities.','火灾造成数人受伤，但无人死亡。'),('The campaign aims to reduce road fatalities.','这项活动旨在减少道路交通死亡。'),sources=['https://www.etymonline.com/word/fatality']),
E('fatalism','/ˈfeɪtəlɪzəm/','宿命论；听天由命的态度','觉得结局早就定了，自己怎样行动也改变不了。','fatal 保留“命运所定”的旧义，加 -ism 形成观念名词；不是“认为一切都会死人”。',FATAL+[['英语 fatal + -ism → fatalism','命运不可改变的观念；接受一切已定的态度']],'哲学讨论可以很精细；日常说 fatalism，常批评一种“反正没用”的消极接受。它与冷静不同：冷静的人仍可能积极寻找办法。','a sense of fatalism；reject fatalism；accept something with fatalism。','pessimism 认为结果会坏；fatalism 认为结果无法改变。一个判断结果，一个判断自己有没有改变余地。',('Her fatalism made it difficult to persuade her to try again.','她听天由命的态度让人很难说服她再试一次。'),('The novel challenges the idea that fatalism is the only response to suffering.','这部小说质疑了面对苦难只能听天由命的想法。'),sources=['https://www.etymonline.com/word/fatalism']),
E('fatalistic','/ˌfeɪtəˈlɪstɪk/','宿命论的；听天由命的','面对事情时，总觉得“该发生就会发生，我也改变不了”。','由 fatalist“宿命论者”加 -ic；fatalist 与 fatalism 都沿 fatal 的命运义发展，不是 fatal“致命”直接加 -istic。',FATAL+[['英语 fatal 一系 → fatalist → fatalistic','认为受命运支配的人 → 持这种态度的']],'a fatalistic attitude 常说一种处事心态。它可以带平静接受，也可以带放弃努力，要看语境；不必每次都涉及完整哲学学说。','a fatalistic attitude；a fatalistic view of life；become fatalistic。','realistic 是按实际条件判断；fatalistic 容易把可改变和不可改变的事都交给命运。',('He took a fatalistic view of the delay and made no attempt to find another route.','他对延误听天由命，也没尝试寻找其他路线。'),('The character becomes less fatalistic as she learns to make her own choices.','这个人物学会自己作选择后，不再那么听天由命。'))
])
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());family=next(r['family'] for r in m['roots'] if r['id']=='C0399');owned=set(m['owned_words'])
EX={w:'接拉丁 fascināre／fascinum“施咒、迷惑”，其更早来源不明；与 fārī 的联系至多是某些分析中的形式影响，不能确认为说话词根的派生。' for w in ['fascinate','fascination']}
ROOT=[dict(id='C0399',meaning='说；承认；流传的话',core='话说出口，可以成为名声、故事、宣言，也可以被理解为命运已定',image='人人谈论形成 fame；说出的故事形成 fable；已经说定的预言联系 fate；还不会说话是 infant；容易交谈是 affable；说不出来是 ineffable。',intro='拉丁 fārī 是说话，fāma 是传闻和名声，fābula 是故事。同族的 fatērī 则偏承认、表明，形成 confess 与 profess。抓住“谁在说、说出了什么、能不能说”，这组看似分散的单词就有了具体场景。',forms='fa- 在 fame、fable、fate 中较显眼，在 infant、affable、ineffable 中藏得较深；fatērī 的分词词干出现为 fess-。不是所有 fa- 开头的词都同源：fascinate、fascination 的远源不明，本页不归入确定词族。',branches=[['被人谈论的名声','fame、famous、famed、famously、infamous、infamously、infamy、defame、defamation、defamatory'],['故事与非凡程度','fable、fabulous、fabulously'],['说定的命运与后果','fate、fateful、fatal、fatally、fatality、fatalism、fatalistic、nefarious'],['说话能力与成长','infant、infancy、infantile、infantry、infantryman'],['说得出与好交谈','affable、affability、affably、ineffable、ineffability、preface'],['公开承认和声明','confess、confession、confessional、confessor、profess、professed、profession、professional、professor'],['来源有分歧的旁支','bifarious：确定来自拉丁 bifariam／bifarius；更早成分是否接“说”，词典分析不同']],contrasts='famous 是有名，infamous 是恶名，并非不出名。fateful 是影响命运，fatal 是致命。affable 是人好交谈，ineffable 是感受难表达。bifarious 的 -fariam 有“说”和“放置”两种远源分析，只作争议旁支，不画确定同源。',practice='分别用 fame、infamy 说两种名声；用 fateful、fatal 对比重大与致命。再把 confess 和 profess 放进一句话：一个人可以公开表明信念，也可以坦白自己没有做到。',words=[w for w in family if w not in EX],exclude=EX,sources=['https://www.etymonline.com/word/fame','https://www.etymonline.com/word/infantry','https://www.etymonline.com/word/fascinate','https://www.etymonline.com/word/bifarious','https://www.merriam-webster.com/dictionary/bifarious'])]
assert {w['word'] for w in W}==(set(family)&owned)-set(EX)
assert len({w['word'] for w in W})==len(W)
for w in W:
 assert len(w['examples'])>=2 and len(w['history'])>=2 and w['ipa'],w['word']
 assert all(len(n)==2 and all(isinstance(v,str) and v for v in n) for n in w['history']),w['word']
for k,d in [('roots',ROOT),('words',W)]: (OUT/f'{k}_batch200_spec_33_fa.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print('C0399',len(W),'new',len(ROOT[0]['words']),'references',sum(len(w['examples']) for w in W),'examples')
